const shopifyOrders = $node["Shopify Trigger (New Order)"].json;
const etsyReceipts = $node["Etsy API - Fetch New Orders"].json.results || [];

const unified = [];

// Process Shopify orders
if (shopifyOrders) {
  shopifyOrders.forEach(order => {
    unified.push({
      source: 'shopify',
      orderId: order.id,
      orderNumber: order.order_number,
      customerEmail: order.email,
      customerName: `${order.billing_address?.first_name || ''} ${order.billing_address?.last_name || ''}`.trim(),
      customerPhone: order.billing_address?.phone,
      total: order.total_price,
      currency: order.currency,
      lineItems: order.line_items.map(item => ({
        title: item.title,
        quantity: item.quantity,
        price: item.price,
        sku: item.sku,
        productType: item.product_type
      })),
      createdAt: order.created_at
    });
  });
}

// Process Etsy receipts
etsyReceipts.forEach(receipt => {
  unified.push({
    source: 'etsy',
    orderId: receipt.receipt_id,
    orderNumber: receipt.receipt_id.toString(),
    customerEmail: receipt.buyer_email,
    customerName: receipt.name,
    customerPhone: null,
    total: receipt.grandtotal?.amount / 100 || 0,
    currency: receipt.grandtotal?.currency_code || 'USD',
    lineItems: receipt.transactions.map(t => ({
      title: t.title,
      quantity: t.quantity,
      price: t.price?.amount / 100 || 0,
      sku: t.sku,
      productType: t.is_digital ? 'Digital' : 'Physical'
    })),
    createdAt: receipt.creation_tsz ? new Date(receipt.creation_tsz * 1000).toISOString() : new Date().toISOString()
  });
});

return unified;

const isRepeatCustomer = $json.properties?.hs_analytics_num_visits > 1;
const isHighValue = $json.total > 100;
const isDigital = $json.lineItems.some(i => i.productType === 'Digital');

return [{
  json: {
    ...$json,
    tags: [
      ...($json.tags || []),
      ...(isRepeatCustomer ? ['repeat-customer'] : []),
      ...(isHighValue ? ['high-value'] : []),
      ...(isDigital ? ['digital-buyer'] : ['physical-buyer'])
    ],
    sendReviewRequest: isRepeatCustomer && !isDigital // Physical product repeat buyers get review request
  }
}];
